"""civ4_classic.yaml is generated by gen_classic.py from civ4_bts.yaml. The set
for the base game and Warlords must not drift from the Beyond the Sword set when
only the Beyond the Sword spec is edited."""
import unittest

import yaml

from polyhost.res.overlay_sources.civ4 import gen_classic


class Civ4ClassicSpecTest(unittest.TestCase):

    def test_the_committed_classic_spec_matches_gen_classic(self):
        committed = (gen_classic.HERE / "civ4_classic.yaml").read_text(encoding="utf-8")
        self.assertEqual(committed, gen_classic.render(),
                         "civ4_classic.yaml is stale: run "
                         "python polyhost/res/overlay_sources/civ4/gen_classic.py")

    def test_the_classic_spec_has_every_bts_binding_not_marked(self):
        def load(name):
            return yaml.safe_load((gen_classic.HERE / name).read_text(encoding="utf-8"))
        bts = load("civ4_bts.yaml")["bindings"]
        classic = load("civ4_classic.yaml")["bindings"]
        kept = [b for b in bts if b.get("classic", True)]
        self.assertEqual(classic, kept)
        self.assertLess(len(classic), len(bts))


if __name__ == "__main__":
    unittest.main()
